def top_k(lst, k):
    if k == 0 or lst == []:
        return []
    elif k == 0:
        return lst
    else:
        final = []
        while lst:
            element = max(lst)
            final += [element,]
            lst.remove(element)
            if len(final) == k:
                break
        return final

def top_k(lst, k):
    i, result = max(lst), []
    while len(result) < k:
        if i in lst:
            result.append(i)
            lst.remove(i)
        elif i not in lst:
            i -= 1
            continue
    return result

def top_k(lst, k):
    #top k in descending order
    sort = []
    x=len(lst)
    while len(lst)>x-k:
        largest = lst[0]
        for element in lst:
            if element > largest:
                largest = element
        lst.remove(largest)
        sort.append(largest)
    return sort

def top_k(lst, k):
    sorted_lst = []
    while lst:
        biggest = lst[0]
        for n in range(len(lst)):
            if lst[n] >= biggest:
                biggest = lst[n]
        lst.remove(biggest)
        sorted_lst.append(biggest)
    return sorted_lst[0:k]

